# This is a logging program specifically tuned for TICC serial data output.

import serial
import argparse
import sys
import time

def serial_logger(device, output_file, baud_rate=115200, timeout=10, 
                  echo=False, reset_arduino=True, log_comments=True, 
                  skip_pre_startup=True, flush_immediately=True):
    """
    Logs TICC data from a serial port to a file.

    Args:
        device (str): The serial port device (e.g., 'COM3' on Windows, '/dev/ttyUSB0' on Linux).
        output_file (str): The name of the file to write the logged data.
        baud_rate (int): The baud rate for the serial connection (default: 115200).
        timeout (int): The read timeout in seconds (default: 10).
        echo (bool):  If true, echo output to console (default: False).
        reset_arduino (bool): If true, toggle DTR and RTS to reset Arduino when opening serial port (default: True).
        log_comments (bool): If true, log lines beginning with '#' (default: True).
        skip_pre_startup (bool): If true, skip all output before the first line beginning with '#' (default: True).
                                 Automatically set based on reset_arduino: True when resetting, False otherwise.
        flush_immediately (bool): If true, flush data to disk after each line (default: True).
    """
    print(f"Opening serial port {device} with baud rate {baud_rate}...")
    try:
        ser = serial.Serial(
            port=device,
            baudrate=baud_rate,
            bytesize=serial.EIGHTBITS,
            parity=serial.PARITY_NONE,
            stopbits=serial.STOPBITS_ONE,
            timeout=timeout
        )
        print(f"Serial port {device} opened successfully.")
        
        # Reset Arduino by toggling DTR and RTS if requested
        if reset_arduino:
            print("Resetting Arduino...")
            ser.setDTR(False)
            ser.setRTS(False)
            time.sleep(0.1)
            ser.setDTR(True)
            ser.setRTS(True)
            time.sleep(2)  # Give Arduino time to reset and start up
            print("Arduino reset complete.")
    except serial.SerialException as e:
        print(f"Error opening serial port {device}: {e}")
        sys.exit(1)

    print(f"Logging data to {output_file}. Press Ctrl-C to stop.")

    try:
        # TICC outputs standard 7-bit ASCII, so we use 'ascii' encoding
        with open(output_file, 'w', encoding='ascii') as f:
            startup_seen = False  # Track if we've seen the first startup line
            
            while True:
                # Read a line of data, decode it as ASCII, and remove leading/trailing whitespace
                line = ser.readline().decode('ascii').strip()
                if line:
                    # Check if this is a comment line (starts with '#')
                    is_comment = line.startswith('#')
                    
                    # If we're skipping pre-startup output and haven't seen startup yet
                    if skip_pre_startup and reset_arduino and not startup_seen:
                        if is_comment:
                            startup_seen = True  # First comment line marks startup
                        else:
                            continue  # Skip non-comment lines before startup
                    
                    # Filter out comment lines unless log_comments is True
                    if is_comment and not log_comments:
                        if echo:
                            print(line)  # Still echo to console if requested
                        continue
                    
                    # Write the line to the file
                    f.write(line + '\n')
                    if flush_immediately:
                        f.flush()  # Force write to disk immediately
                    if echo:
                        print(line)  # Optionally print to console as well
                time.sleep(0.01) # Small delay to prevent busy-waiting
    except KeyboardInterrupt:
        print("\nCtrl-C detected. Closing serial port and file.")
    except Exception as e:
        print(f"An unexpected error occurred during logging: {e}")
    finally:
        if ser.is_open:
            ser.close()
            print("Serial port closed.")

if __name__ == "__main__":
    parser = argparse.ArgumentParser(description="Log TICC data from a serial port to a file.")
    parser.add_argument("device", help="The serial port device (e.g., COM3 or /dev/ttyUSB0).")
    parser.add_argument("output_file", help="The name of the file to write the logged data.")
    parser.add_argument("--baud", type=int, default=115200, help="Baud rate for the serial connection (default: 115200).")
    parser.add_argument("--timeout", type=int, default=10, help="Read timeout in seconds (default: 10).")
    parser.add_argument("--echo", action="store_true", default=False,
                        help="Echo output to console as well as logging to file.")
    parser.add_argument("--no-reset", action="store_true", default=False,
                        help="Don't toggle DTR and RTS to reset Arduino (default: reset is enabled).")
    parser.add_argument("--no-header", action="store_true", default=False,
                        help="Don't log startup/header lines beginning with '#' (default: log all lines).")
    parser.add_argument("--no-flush", action="store_true", default=False,
                        help="Buffer output instead of flushing to disk after each line (may improve performance).")

    args = parser.parse_args()

    # Automatically determine skip_pre_startup based on reset setting
    # When resetting (default), skip garbage before startup; when not resetting, capture everything
    reset_enabled = not args.no_reset
    skip_pre_startup = reset_enabled

    serial_logger(args.device, args.output_file, args.baud, args.timeout, 
                  args.echo, reset_enabled, not args.no_header,
                  skip_pre_startup, not args.no_flush)

